public sealed class InvoiceProcessor(ILogger<InvoiceProcessor> logger)
{
    [Function("InvoiceProcessor")]
    public async Task RunAsync(
        [BlobTrigger("invoices/{name}")] Stream blob,
        string name,
        [Blob("extracted/{name}.json", FileAccess.Write)] Stream output)
    {
        logger.LogInformation("Processing {Name}", name);

        var invoice = InvoiceParser.Parse(blob);

        await JsonSerializer.SerializeAsync(output, invoice);
    }
}
